1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
32	// 给出的完整字符串逐字节参与比较，允许包含 U+0000 与非法 UTF-8 字节
33	// （后者靠记录中的 identity_raw 兜底字段跨重开保真）。不能用分隔符把两个
34	// 字段拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、
35	// 请求号 "c" 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
36	type idemIdentity struct {
37		submitter string
38		requestID string
39	}
40	
41	type Store struct {
42		dir string
43	
44		mu     sync.Mutex
45		jobs   []*storedJob // 严格按作业号（即提交先后）排列
46		byID   map[uint64]*storedJob
47		idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
48		nextID uint64
49		closed bool
50	
51		now func() time.Time
52	
53		runningID uint64
54		waitCh    chan struct{}
55		stopCh    chan struct{}
56		stopping  atomic.Bool
57		wg        sync.WaitGroup
58	
59		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
60		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
61		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
62		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
63	
64		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
65		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
66		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
67		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
68		persistFault func(j *storedJob) error
69	}
70	
71	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
72	//
73	// 恢复语义：
74	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
75	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
76	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
77	//   - 成功状态始终与完整归档同时可见。
78	func Open(dir string, opts ...Option) (*Store, error) {
79		if err := os.MkdirAll(dir, 0o700); err != nil {
80			return nil, err
81		}
82		jobs, maxID, err := loadDir(dir)
83		if err != nil {
84			return nil, err
85		}
86		s := &Store{
87			dir:    dir,
88			jobs:   jobs,
89			byID:   make(map[uint64]*storedJob),
90			idem:   make(map[idemIdentity]uint64),
91			nextID: maxID + 1,
92			now:    wallClock{}.Now,
93			waitCh: make(chan struct{}, 1),
94			stopCh: make(chan struct{}),
95		}
96		for _, opt := range opts {
97			opt(s)
98		}
99		for _, j := range jobs {
100			s.byID[j.id] = j
101			if j.requestID != "" {
102				s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
103			}
104		}
105		// 重建失败/取消作业对排队下游的阻断。
106		s.cascadeLocked()
107		s.wg.Add(1)
108		go s.worker()
109		return s, nil
110	}
111	
112	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
113	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
114	func (s *Store) Close() error {
115		s.mu.Lock()
116		if s.closed {
117			s.mu.Unlock()
118			return nil
119		}
120		s.closed = true
121		var running *storedJob
122		if s.runningID != 0 {
123			running = s.byID[s.runningID]
124		}
125		s.mu.Unlock()
126	
127		if s.stopping.CompareAndSwap(false, true) {
128			close(s.stopCh)
129		}
130		// 中止正在运行的计算。
131		if running != nil {
132			running.canceled.Store(true)
133		}
134		s.notify()
135		s.wg.Wait()
136		return nil
137	}
138	
139	// Submit 接受一次作业提交。
140	//
141	// 空序列返回 [ErrEmptySequence]；依赖列表结构不合法（单依赖与列表同时启用、
142	// 含零或重复作业号）返回 [ErrInvalidDependency]——这些请求本身的格式错误先于
143	// 幂等判定拒绝，即使复用已接受的请求号也不例外。
144	//
145	// 非空请求号命中同一提交人的已接受请求时，幂等判定先于“引用的上游必须存在”
146	// 校验：内容（整数序列及次序、种子、有序依赖内容）完全一致时返回原作业的
147	// 当前详情且不返回错误，即使其直接上游记录在重开归档后已缺失、原作业已因此
148	// 被改判为失败；内容不一致返回 [ErrIdempotencyConflict]（同时返回原作业视图，
149	// 仍引用缺失上游时在原因中一并指出），原记录保持原样。重复提交不创建新作业、
150	// 不补建缺失上游、不重新排队失败作业、也不改写原始参数或失败记录。
151	//
152	// 未命中已接受请求的新请求（提交人不同、请求号不同或请求号为空）引用不存在
153	// 的依赖时返回 [ErrDependencyNotFound]；上述拒绝都不产生记录，也不占用请求号。
154	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
155	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
156		s.mu.Lock()
157		defer s.mu.Unlock()
158		if s.closed || s.stopping.Load() {
159			return nil, ErrStoreClosed
160		}
161		if len(req.Values) == 0 {
162			return nil, ErrEmptySequence
163		}
164		// 先校验与上游存在性无关的列表结构（单依赖与列表互斥、零与重复作业号），
165		// 这类拒绝不依赖内存索引，对新请求与幂等重放一视同仁。
166		if err := s.validateDependencyShapeLocked(&req); err != nil {
167			return nil, err
168		}
169		deps := requestDeps(&req)
170		if req.RequestID != "" {
171			key := idemIdentity{req.Submitter, req.RequestID}
172			if origID, ok := s.idem[key]; ok {
173				orig := s.byID[origID]
174				// 幂等重放先于“引用的上游必须存在”的校验：重新打开归档后原作业
175				// 直接上游的记录可能已经缺失，原作业也因此被改判为失败并落盘。
176				// 只要本次提交的整数序列及次序、种子与有序依赖内容和已接受请求
177				// 完全一致（单依赖写法与只含同一作业号的列表等价），就返回原作业
178				// 的当前详情——不重建缺失上游、不重新排队、不补算、不改写记录。
179				if sameContent(orig, &req) {
180					return s.viewLocked(orig), nil
181				}
182				return s.viewLocked(orig),
183					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d，且本次内容与原请求不一致%s，原记录保持原样",
184						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID,
185						s.missingDependencyNoteLocked(deps))
186			}
187		}
188		// 新请求（请求号为空，或该提交人首次使用此请求号）仍要求每个直接上游
189		// 都存在；引用不存在上游的提交被拒绝，不产生记录，也不占用请求号。
190		// 此检查必须位于幂等判定之后：上面的重放/冲突分支可能引用缺失的上游。
191		if err := s.validateDependenciesExistLocked(deps); err != nil {
192			return nil, err
193		}
194	
195		now := s.now().UTC()
196		j := &storedJob{
197			id:           s.nextID,
198			submitter:    req.Submitter,
199			requestID:    req.RequestID,
200			seed:         req.Seed,
201			values:       append([]int64(nil), req.Values...),
202			dependencies: append([]uint64(nil), deps...),
203			queuedAt:     now,
204			status:       StatusQueued,
205		}
206		// 先持久化，接受之后该提交即不可丢失。
207		if err := s.persist(j); err != nil {
208			return nil, err
209		}
210		s.nextID++
211		s.jobs = append(s.jobs, j)
212		s.byID[j.id] = j
213		if req.RequestID != "" {
214			s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
215		}
216		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
217		s.cascadeLocked()
218		s.notifyLocked()
219		return s.viewLocked(j), nil
220	}
221	
222	// requestDeps 规范化一次提交的直接上游作业号列表：
223	// 非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含一个作业号的列表；
224	// 两者皆无则为 nil。调用前须先经 [Store.validateDependencyShapeLocked] 与
225	// （新请求路径上的）[Store.validateDependenciesExistLocked] 校验。
226	func requestDeps(req *SubmitRequest) []uint64 {
227		if len(req.Dependencies) > 0 {
228			return append([]uint64(nil), req.Dependencies...)
229		}
230		if req.HasDependency {
231			return []uint64{req.DependencyID}
232		}
233		return nil
234	}
235	
236	// validateDependencyShapeLocked 在持锁状态下校验提交依赖列表中与上游存在性
237	// 无关的结构问题：
238	//   - 单依赖方式与非空列表同时启用 → 拒绝；
239	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）。
240	//
241	// 该校验先于幂等判定执行：空整数序列、依赖号为零、重复依赖与两种写法
242	// 同时启用都属于请求本身的格式错误，即使提交人+请求号与已接受请求相同
243	// 也仍返回原有的对应拒绝。
244	func (s *Store) validateDependencyShapeLocked(req *SubmitRequest) error {
245		if req.HasDependency && len(req.Dependencies) > 0 {
246			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
247		}
248		deps := requestDeps(req)
249		seen := make(map[uint64]struct{}, len(deps))
250		for _, id := range deps {
251			if id == 0 {
252				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
253			}
254			if _, dup := seen[id]; dup {
255				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
256			}
257			seen[id] = struct{}{}
258		}
259		return nil
260	}
261	
262	// validateDependenciesExistLocked 校验规范化后的依赖列表只引用当前归档中
263	// 存在的作业。仅适用于幂等判定之后的新请求：已接受请求的重放（或内容
264	// 冲突）即使引用了重开后缺失的上游，也要返回原作业而不是被这里拒绝。
265	//
266	// 任一拒绝都不产生记录，也不占用幂等请求号。
267	func (s *Store) validateDependenciesExistLocked(deps []uint64) error {
268		for _, id := range deps {
269			if s.byID[id] == nil {
270				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
271			}
272		}
273		return nil
274	}
275	
276	// missingDependencyNoteLocked 在幂等冲突时补充说明：若本次（与原请求内容
277	// 不一致的）提交仍引用已经缺失的上游，明确指出缺失的作业号，使冲突原因
278	// 不会被误读成仅仅是上游不存在。
279	func (s *Store) missingDependencyNoteLocked(deps []uint64) string {
280		for _, id := range deps {
281			if s.byID[id] == nil {
282				return fmt.Sprintf("；本次引用的直接上游作业 %d 记录已缺失", id)
283			}
284		}
285		return ""
286	}
287	
288	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
289	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
290	func sameContent(j *storedJob, req *SubmitRequest) bool {
291		if j.seed != req.Seed {
292			return false
293		}
294		rd := requestDeps(req)
295		if len(j.dependencies) != len(rd) {
296			return false
297		}
298		for i := range j.dependencies {
299			if j.dependencies[i] != rd[i] {
300				return false
301			}
302		}
303		if len(j.values) != len(req.Values) {
304			return false
305		}
306		for i := range j.values {
307			if j.values[i] != req.Values[i] {
308				return false
309			}
310		}
311		return true
312	}
313	
314	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
315	func (s *Store) Get(id uint64) (*Job, error) {
316		s.mu.Lock()
317		defer s.mu.Unlock()
318		j := s.byID[id]
319		if j == nil {
320			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
321		}
322		return s.viewLocked(j), nil
323	}
324	
325	// Cancel 请求取消作业。
326	//
327	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
328	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
329	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
330	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
331	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
332	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
333	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
334	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
335	func (s *Store) Cancel(id uint64) (*Job, error) {
336		s.mu.Lock()
337		defer s.mu.Unlock()
338		if s.closed {
339			return nil, ErrStoreClosed
340		}
341		j := s.byID[id]
342		if j == nil {
343			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
344		}
345		switch j.status {
346		case StatusCanceled:
347			return s.viewLocked(j), nil
348		case StatusSucceeded, StatusFailed:
349			return s.viewLocked(j),
350				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
351		}
352	
353		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
354		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
355		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
356		// 不能把这次取消当作已完成。
357		now := s.now().UTC()
358		prevStatus := j.status
359		prevFinishedAt := j.finishedAt
360		prevReason := j.failureReason
361		prevBlocker := j.blockerID
362		prevEffective := j.effectiveValues
363		prevArchive := j.archive
364		j.status = StatusCanceled
365		j.failureReason = ""
366		j.blockerID = 0
367		if j.finishedAt.IsZero() {
368			j.finishedAt = now
369		}
370		j.effectiveValues = nil
371		j.archive = nil
372		if err := s.persist(j); err != nil {
373			j.status = prevStatus
374			j.finishedAt = prevFinishedAt
375			j.failureReason = prevReason
376			j.blockerID = prevBlocker
377			j.effectiveValues = prevEffective
378			j.archive = prevArchive
379			return nil, err
380		}
381	
382		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
383		j.canceled.Store(true)
384		// 依赖它的等待者一并失败，且继续向更下游传播。
385		s.cascadeLocked()
386		s.notifyLocked()
387		return s.viewLocked(j), nil
388	}
389	
390	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
391	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
392	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
393		s.mu.Lock()
394		defer s.mu.Unlock()
395		if !start.IsZero() && !end.IsZero() && start.After(end) {
396			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
397				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
398		}
399		out := make([]*Job, 0)
400		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
401			if j.submitter != submitter {
402				continue
403			}
404			if !start.IsZero() && j.queuedAt.Before(start) {
405				continue
406			}
407			if !end.IsZero() && j.queuedAt.After(end) {
408				continue
409			}
410			out = append(out, s.viewLocked(j))
411		}
412		return out, nil
413	}
414	
415	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
416	//
417	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
418	// 扫描即可让阻断沿链条传播到最下游。选择直接阻断者、确定根因与构造失败
419	// 原因统一走 blocker.go 中的规则（与重开归档同一套）：作业有多个直接上游时
420	// 按保存的依赖顺序选取最靠前的已失败/取消者，根因沿该上游已有的阻断信息
421	// 保留；作业一旦失败，其原因不再被后来发生的上游状态变化改写。
422	func (s *Store) cascadeLocked() {
423		for _, j := range s.jobs {
424			if j.status != StatusQueued || len(j.dependencies) == 0 {
425				continue
426			}
427			directID, direct, blocked := pickBlockingUpstream(j, s.byID, runtimeUpstreamBlocked)
428			if !blocked {
429				continue
430			}
431			root := blockerRoot(direct, directID)
432			s.markFailedLocked(j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
433		}
434	}
435	
436	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
437	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
438	// 该作业就被跳过，不挡住后面可运行的作业。
439	func (s *Store) pickRunnableLocked() *storedJob {
440		for _, j := range s.jobs {
441			if j.status != StatusQueued {
442				continue
443			}
444			if len(j.dependencies) == 0 {
445				return j
446			}
447			ready := true
448			for _, id := range j.dependencies {
449				dep := s.byID[id]
450				if dep == nil || dep.status != StatusSucceeded {
451					ready = false
452					break
453				}
454			}
455			if ready {
456				return j
457			}
458		}
459		return nil
460	}
461	
462	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
463	func (s *Store) notifyLocked() {
464		select {
465		case s.waitCh <- struct{}{}:
466		default:
467		}
468	}
469	
470	// notify 在不持锁时唤醒 worker。
471	func (s *Store) notify() {
472		s.mu.Lock()
473		s.notifyLocked()
474		s.mu.Unlock()
475	}
476	
477	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
478	func (s *Store) persistRetry(j *storedJob, attempts int) error {
479		var err error
480		for i := 0; i < attempts; i++ {
481			if err = s.persist(j); err == nil {
482				return nil
483			}
484		}
485		return err
486	}
487	
488	// worker 是本地唯一的计算执行体。
489	func (s *Store) worker() {
490		defer s.wg.Done()
491		for {
492			s.mu.Lock()
493			if s.stopping.Load() {
494				s.mu.Unlock()
495				return
496			}
497			j := s.pickRunnableLocked()
498			if j == nil {
499				ch := s.waitCh
500				s.mu.Unlock()
501				select {
502				case <-ch:
503				case <-s.stopCh:
504				}
505				continue
506			}
507	
508			// 进入运行并原子持久化该状态。
509			j.status = StatusRunning
510			j.startedAt = s.now().UTC()
511			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
512			inputs := append([]int64(nil), j.values...)
513			for _, id := range j.dependencies {
514				if dep := s.byID[id]; dep != nil && dep.archive != nil {
515					inputs = append(inputs, dep.archive.Sum)
516				}
517			}
518			seed := j.seed
519			s.runningID = j.id
520			if err := s.persistRetry(j, 3); err != nil {
521				// 连运行状态都无法落盘：保守地失败，不进行计算。
522				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
523				s.runningID = 0
524				s.cascadeLocked()
525				s.notifyLocked()
526				s.mu.Unlock()
527				continue
528			}
529			s.mu.Unlock()
530	
531			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
532			doCompute := s.compute
533			if doCompute == nil {
534				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
535					return computeResult(in, sd, c)
536				}
537			}
538			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
539	
540			s.mu.Lock()
541			s.runningID = 0
542			switch {
543			case j.status == StatusCanceled:
544				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
545				j.archive = nil
546				j.effectiveValues = nil
547				_ = s.persistRetry(j, 3)
548				s.cascadeLocked()
549			case s.stopping.Load():
550				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
551				s.cascadeLocked()
552			case !ok:
553				s.markFailedLocked(j, reason, 0)
554				s.cascadeLocked()
555			default:
556				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
557				completed := s.now().UTC()
558				a := newArchive(j, inputs, sum, sumSq, completed)
559				j.effectiveValues = append([]int64(nil), inputs...)
560				j.status = StatusSucceeded
561				j.finishedAt = completed
562				j.failureReason = ""
563				j.blockerID = 0
564				j.archive = a
565				if err := s.persistRetry(j, 3); err != nil {
566					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
567					j.archive = nil
568					j.effectiveValues = nil
569					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
570					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
571					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
572					s.cascadeLocked()
573				}
574			}
575			s.notifyLocked()
576			s.mu.Unlock()
577		}
578	}
579	
580	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
581	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
582		j.status = StatusFailed
583		j.failureReason = reason
584		j.blockerID = blocker
585		if j.finishedAt.IsZero() {
586			j.finishedAt = s.now().UTC()
587		}
588		j.archive = nil
589		j.effectiveValues = nil
590		_ = s.persistRetry(j, 3)
591	}
592	
593	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
594	// 上游作业号只作记录，不参与任何摘要与校验值。
595	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
596		inDigest := inputsDigestHex(effective, j.seed)
597		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
598		log := buildLog(effective, j.seed, sum, sumSquares)
599		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
600		var firstDep uint64
601		if len(j.dependencies) > 0 {
602			firstDep = j.dependencies[0]
603		}
604		return &Archive{
605			JobID:           j.id,
606			Submitter:       j.submitter,
607			RequestID:       j.requestID,
608			IdentityRaw:     rawIdentity(j.submitter, j.requestID),
609			Seed:            j.seed,
610			Values:          append([]int64(nil), j.values...),
611			HasDependency:   len(j.dependencies) > 0,
612			DependencyID:    firstDep,
613			Dependencies:    append([]uint64(nil), j.dependencies...),
614			EffectiveValues: append([]int64(nil), effective...),
615			InputsDigest:    inDigest,
616			Sum:             sum,
617			SumOfSquares:    sumSquares,
618			ResultDigest:    resDigest,
619			Log:             log,
620			Checksum:        checksum,
621			CompletedAt:     completedAt,
622		}
623	}
624	
625	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
626	func (s *Store) viewLocked(j *storedJob) *Job {
627		v := &Job{
628			ID:              j.id,
629			Submitter:       j.submitter,
630			RequestID:       j.requestID,
631			Seed:            j.seed,
632			Values:          append([]int64(nil), j.values...),
633			Dependencies:    append([]uint64(nil), j.dependencies...),
634			QueuedAt:        j.queuedAt,
635			StartedAt:       j.startedAt,
636			FinishedAt:      j.finishedAt,
637			Status:          j.status,
638			FailureReason:   j.failureReason,
639			BlockerID:       j.blockerID,
640			EffectiveValues: append([]int64(nil), j.effectiveValues...),
641		}
642		v.HasDependency = len(j.dependencies) > 0
643		if len(j.dependencies) > 0 {
644			v.DependencyID = j.dependencies[0]
645		}
646		if j.status == StatusQueued {
647			v.WaitReason = WaitSlot
648			// 列出尚未成功归档的直接上游，保持提交时的顺序。
649			for _, id := range j.dependencies {
650				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
651					v.PendingDependencies = append(v.PendingDependencies, id)
652				}
653			}
654			if len(v.PendingDependencies) > 0 {
655				v.WaitReason = WaitDependency
656			}
657		}
658		if j.archive != nil {
659			a := *j.archive
660			a.Values = append([]int64(nil), j.archive.Values...)
661			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
662			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
663			if j.archive.IdentityRaw != nil {
664				raw := *j.archive.IdentityRaw
665				a.IdentityRaw = &raw
666			}
667			v.Archive = &a
668		}
669		return v
670	}
671	
672	// Dir 返回归档目录路径。
673	func (s *Store) Dir() string { return s.dir }
674

