1	package numeric
2	
3	import (
4		"crypto/sha256"
5		"encoding/binary"
6		"encoding/hex"
7		"fmt"
8		"math/bits"
9		"strings"
10	)
11	
12	// addInt64 返回 a+b；结果超出 int64 时 ok 为 false。
13	func addInt64(a, b int64) (r int64, ok bool) {
14		r = a + b
15		// 同号相加却变号即溢出。
16		if (a >= 0 && b >= 0 && r < 0) || (a < 0 && b < 0 && r >= 0) {
17			return 0, false
18		}
19		return r, true
20	}
21	
22	// squareUint 返回 |x|^2 的 128 位无符号表示 (hi, lo)。
23	// x 为 math.MinInt64 时 uint64(-x) 恰为 2^63，绝对值仍然正确。
24	func squareUint(x int64) (hi, lo uint64) {
25		var m uint64
26		if x >= 0 {
27			m = uint64(x)
28		} else {
29			m = uint64(-x)
30		}
31		return bits.Mul64(m, m)
32	}
33	
34	// computeResult 对有效输入（原始序列，末尾可能已追加依赖总和）做求和与平方和。
35	//
36	// canceled 在计算过程中被置位时（例如运行中被取消、归档关闭）尽快中止，
37	// 此时不应产生任何成功归档。任一结果超出有符号 64 位整数范围时以失败返回，
38	// 失败原因明确指出是哪一个结果溢出。
39	func computeResult(inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool) {
40		sum = 0
41		var sqLo, sqHi uint64 // 平方和的 128 位累加器
42		for i, v := range inputs {
43			if canceled != nil && i&0x3f == 0 && canceled() {
44				return 0, 0, "", false
45			}
46	
47			s, sumOK := addInt64(sum, v)
48			if !sumOK {
49				return 0, 0, "总和超出有符号 64 位整数范围", false
50			}
51			sum = s
52	
53			shi, slo := squareUint(v)
54			lo, carry := bits.Add64(sqLo, slo, 0)
55			hi := sqHi + shi + carry
56			sqLo, sqHi = lo, hi
57			// 平方和非负，一旦超过 MaxInt64 就不可能再回到范围内。
58			if sqHi != 0 || sqLo > 1<<63-1 {
59				return 0, 0, "平方和超出有符号 64 位整数范围", false
60			}
61		}
62		sumSquares = int64(sqLo)
63		return sum, sumSquares, "", true
64	}
65	
66	// digestWriter 按固定大端编码写入摘要输入，避免任何长度/符号歧义。
67	type digestWriter struct {
68		buf []byte
69	}
70	
71	func (w *digestWriter) writeBytes(b []byte) { w.buf = append(w.buf, b...) }
72	
73	func (w *digestWriter) writeTag(tag string) {
74		w.buf = append(w.buf, byte(len(tag)))
75		w.buf = append(w.buf, tag...)
76	}
77	
78	func (w *digestWriter) writeInt64(v int64) {
79		var b [8]byte
80		binary.BigEndian.PutUint64(b[:], uint64(v))
81		w.buf = append(w.buf, b[:]...)
82	}
83	
84	func (w *digestWriter) writeUint64(v uint64) {
85		var b [8]byte
86		binary.BigEndian.PutUint64(b[:], v)
87		w.buf = append(w.buf, b[:]...)
88	}
89	
90	func sumHex(data []byte) string {
91		s := sha256.Sum256(data)
92		return hex.EncodeToString(s[:])
93	}
94	
95	// inputsDigestHex 只由有效输入序列与种子决定，与作业号、时间无关。
96	func inputsDigestHex(effective []int64, seed int64) string {
97		w := digestWriter{}
98		w.writeTag("numeric/inputs/v1")
99		w.writeInt64(seed)
100		w.writeUint64(uint64(len(effective)))
101		for _, v := range effective {
102			w.writeInt64(v)
103		}
104		return sumHex(w.buf)
105	}
106	
107	// resultDigestHex 只由有效输入、种子与结果决定。
108	func resultDigestHex(effective []int64, seed, sum, sumSquares int64) string {
109		in := inputsDigestHex(effective, seed)
110		raw, _ := hex.DecodeString(in)
111		w := digestWriter{}
112		w.writeTag("numeric/result/v1")
113		w.writeBytes(raw)
114		w.writeInt64(sum)
115		w.writeInt64(sumSquares)
116		return sumHex(w.buf)
117	}
118	
119	// buildLog 生成确定性的人类可读计算日志：不含作业号与时间，
120	// 因此相同有效输入与种子产生完全相同的日志。
121	func buildLog(effective []int64, seed, sum, sumSquares int64) string {
122		var b strings.Builder
123		fmt.Fprintf(&b, "numeric computation log\n")
124		fmt.Fprintf(&b, "seed=%d\n", seed)
125		fmt.Fprintf(&b, "input_count=%d\n", len(effective))
126		for i, v := range effective {
127			fmt.Fprintf(&b, "input[%d]=%d\n", i, v)
128		}
129		fmt.Fprintf(&b, "sum=%d\n", sum)
130		fmt.Fprintf(&b, "sum_of_squares=%d\n", sumSquares)
131		return b.String()
132	}
133	
134	// checksumHex 只由有效输入、种子、结果与计算日志决定。
135	func checksumHex(effective []int64, seed, sum, sumSquares int64, log, resultDigest string) string {
136		raw, _ := hex.DecodeString(resultDigest)
137		w := digestWriter{}
138		w.writeTag("numeric/checksum/v1")
139		w.writeBytes(raw)
140		w.writeInt64(seed)
141		w.writeUint64(uint64(len(effective)))
